/**
 * One raw A2A JSON-RPC call, for the escape hatch: an RPC nobody wrapped stays
 * reachable without a code change.
 *
 * It goes through the same authenticating `fetch` as everything else, and the
 * URL comes from the peer's own card rather than being composed — a peer is
 * free to serve the binding at any path, and guessing `/a2a/v1` would work
 * against this implementation and quietly fail against others.
 */
async rawRpc(url: string, method: string, params: Record<string, unknown>): Promise<unknown> {
  const card = await this.card(url);
  const iface = card.supportedInterfaces.find(
    (candidate) => candidate.protocolBinding === "JSONRPC",
  );
  if (!iface) {
    throw new A2AApiError(`${normalizeBase(url)} advertises no JSON-RPC interface.`, {
      status: 0,
      remedy:
        "Its card lists " +
        (card.supportedInterfaces.map((i) => i.protocolBinding).join(", ") || "nothing") +
        ". The escape hatch speaks JSON-RPC only; use the typed tools for the other bindings.",
    });
  }
  const res = await this.rpcFetch(iface.url, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ jsonrpc: "2.0", id: randomId("rpc"), method, params }),
  });
  const text = await res.text();
  if (!res.ok) {
    const remedy = remedyForStatus(res.status, this.opts.token !== undefined);
    throw new A2AApiError(`${iface.url} answered HTTP ${res.status}: ${text.slice(0, 400)}`, {
      status: res.status,
      ...(remedy ? { remedy } : {}),
    });
  }
  try {
    return JSON.parse(text) as unknown;
  } catch {
    throw new A2AApiError(`${iface.url} answered with something that is not JSON.`, {
      status: res.status,
      errors: text.slice(0, 400),
    });
  }
}

/**
 * Is a peer answering at all? Used by `a2a_auth_status` against our own
 * daemon, where "is it running" is the first question and an exception is the
 * wrong way to answer it.
 */
async probe(url: string): Promise<{ reachable: boolean; card?: AgentCard; error?: string }> {
  try {
    return { reachable: true, card: await this.discover(url) };
  } catch (err) {
    return { reachable: false, error: err instanceof Error ? err.message : String(err) };
  }
}

private async clientFor(url: string): Promise<A2APeerClient> {
  const base = normalizeBase(url);
  const existing = this.clients.get(base);
  if (existing) return existing;
  const client = await this.factory.createFromAgentCard(await this.card(base));
  this.clients.set(base, client);
  return client;
}

server.registerTool(
  "a2a_send_message",
  {
    title: "A2A: Send Message",
    description:
      "Delegate work to another agent over A2A, and record the resulting task locally so " +
      "a2a_list_tasks can track it. Call a2a_discover_agent first for a peer you have not " +
      "used — its skill list is what says whether it can do the thing, and its card is what " +
      "says which binding to speak. Returns as soon as the peer has acknowledged the task, " +
      "WITHOUT waiting for an answer: a peer on this mesh queues work for a " +
      "human-supervised agent, so a blocking send would block for as long as a person takes. " +
      "Poll with `a2a_get_task(refresh: true)`, or park on a2a_wait_for_task. Pass `task_id` " +
      "to add a turn to a task that already exists rather than starting a new one.",
    inputSchema: {
      url: peerUrlArg,
      text: z
        .string()
        .min(1)
        .max(32_000)
        .describe(
          "What you are asking the other agent to do, in plain prose. Be specific about " +
            "absolute paths and repositories — the peer is a different agent with a " +
            'different working directory, e.g. "Run the tests in ~/Projects/example and ' +
            'report which fail". Put bulk content in a file and name the path rather than ' +
            "pasting it: the daemon caps a request body at 1 MB.",
        ),
      task_id: z
        .string()
        .max(128)
        .optional()
        .describe(
          "Continue an existing task by id, instead of creating a new one. Use this to " +
            "answer a peer that moved its task to `input_required`.",
        ),
      context_id: z
        .string()
        .max(128)
        .optional()
        .describe(
          "Group this message with an existing conversation by context id. Omit to let the " +
            "peer assign one.",
        ),
    },
    annotations: { readOnlyHint: false, destructiveHint: false, idempotentHint: false },
  },
  async ({ url, text, task_id, context_id }) =>
    wrap(async () => {
      const peer = normalizeBase(url);
      const { result, sent } = await ctx.peers.sendMessage(peer, {
        text,
        ...(task_id ? { taskId: task_id } : {}),
        ...(context_id ? { contextId: context_id } : {}),
      });

      // A peer may answer with a bare Message instead of a Task — legal in A2A
      // for something it handled without creating one. There is nothing to
      // mirror in that case, and pretending otherwise would put a task id in
      // the store that no peer knows.
      if (!("id" in result)) {
        return {
          peer,
          replied_with: "message",
          text: messageText(result as Message),
          note: "The peer answered directly without creating a task, so nothing was recorded.",
        };
      }

      const task = result as Task;
      // The peer's acknowledgement usually arrives with an empty history — see
      // `PeerClient.sendMessage`. Our own request is the one thing we know for
      // certain, so it goes into the mirror rather than being lost.
      const mirrored: Task = task.history.length === 0 ? { ...task, history: [sent] } : task;
      const record = ctx.store.put(mirrored, { direction: "outbound", peer });
      return {
        peer,
        replied_with: "task",
        task: summarizeTask(record),
        note:
          "Recorded locally as an outbound task. Read the answer later with " +
          "a2a_get_task(refresh: true) — the local copy is a mirror and does not update itself.",
      };

export const registerTools = (server: McpServer, ctx: ToolContext): void => {
  // First and unconditionally: an unconfigured server must still be able to say
  // what it needs, rather than being a connection that closes.
  registerAuthTools(server, ctx);
  registerAgentTools(server, ctx);
  registerTaskTools(server, ctx);
  registerRequestTool(server, ctx);

  if (ctx.allowWrites) registerWriteTools(server, ctx);

export const createServer = (opts: CreateServerOptions): CreatedServer => {
  const { config } = opts;
  const server = new McpServer({ name: SERVER_NAME, version: SERVER_VERSION });

  // Before `connect`: `registerCapabilities` refuses to run once a transport is
  // attached, because capabilities are part of the `initialize` result.
  if (config.channel) declareChannelCapability(server);

  const store = new FileTaskStore({
    stateDir: config.stateDir,
    // The stdio server creates outbound tasks; anything it finds that it did not
    // create came from the daemon and is inbound.
    defaultDirection: "inbound",
    defaultPeer: "unknown",
    ...(opts.logger ? { logger: opts.logger } : {}),
  });

  const peers = new PeerClient({
    stateDir: config.stateDir,
    configuredPeers: config.peers,
    daemonUrl: config.daemonUrl,
    token: config.token,
    maxRetries: config.maxRetries,
    userAgent: USER_AGENT,
    ...(opts.fetch ? { fetch: opts.fetch } : {}),
    ...(opts.logger ? { logger: opts.logger } : {}),
  });

  registerTools(server, {
    config,
    store,
    peers,
    allowWrites: config.allowWrites,
    ...(opts.logger ? { logger: opts.logger } : {}),
  });

  const channel =
    config.channel && opts.watchChannel !== false
      ? startChannelWatcher({
          server,
          store,
          config,
          ...(opts.logger ? { logger: opts.logger } : {}),
        })
      : undefined;

  return { server, store, peers, channel };
};
